package com.inventra.backend.repository; import com.inventra.backend.model.StockReservation; import com.inventra.backend.model.ReservationStatus; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.*; public interface ReservationRepository extends MongoRepository<StockReservation,String> { List<StockReservation> findByOrderId(String orderId); List<StockReservation> findByOrderIdAndStatus(String orderId,ReservationStatus status); List<StockReservation> findByWarehouseIdAndProductIdAndStatus(String warehouseId,String productId,ReservationStatus status); }
